<?php namespace Vedairo\Storage; final class LocalStorage {public function __construct(private string $root){if(!is_dir($root))mkdir($root,0775,true);}public function put(string $path,string $contents):string{$full=rtrim($this->root,'/\\').DIRECTORY_SEPARATOR.ltrim($path,'/\\');$dir=dirname($full);if(!is_dir($dir))mkdir($dir,0775,true);file_put_contents($full,$contents,LOCK_EX);return $path;}public function get(string $path):string{return file_get_contents(rtrim($this->root,'/\\').DIRECTORY_SEPARATOR.ltrim($path,'/\\'));}public function delete(string $path):bool{$f=rtrim($this->root,'/\\').DIRECTORY_SEPARATOR.ltrim($path,'/\\');return is_file($f)?unlink($f):false;}public function exists(string $path):bool{return is_file(rtrim($this->root,'/\\').DIRECTORY_SEPARATOR.ltrim($path,'/\\'));}}
